<?php session_start(); require_once __DIR__.'/../config/config.php'; require_admin(); $pdo=db(); $msg=''; if(isset($_GET['logout'])){session_destroy();header('Location:login.php');exit;} if($_SERVER['REQUEST_METHOD']==='POST'){ $action=$_POST['action']??''; if($action==='design'){foreach(['green','green2','navy','gold','white','muted','primary','accent','lightBg','darkBg','lightText','darkText','fontColor','fontFamily'] as $k){if(isset($_POST[$k]))set_setting($k,trim((string)$_POST[$k]));}$msg='تم حفظ إعدادات الألوان والخط.';} elseif($action==='content'){set_setting('site_name_ar',trim($_POST['site_name_ar']??''));set_setting('site_name_en',trim($_POST['site_name_en']??''));set_setting('whatsapp',preg_replace('/\D+/','',$_POST['whatsapp']??''));set_setting('email',trim($_POST['email']??''));$msg='تم حفظ بيانات الموقع.';} } $keys=['green','green2','navy','gold','white','muted','primary','accent','lightBg','darkBg','lightText','darkText','fontColor']; ?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Thaer Media Admin</title><link rel="stylesheet" href="admin.css"></head><body><aside><h2>THAER<br><span>MEDIA</span></h2><a href="#design">🎨 الألوان والخط</a><a href="#content">⚙️ بيانات الموقع</a><a href="../" target="_blank">🌐 معاينة الموقع</a><a href="?logout=1">🚪 خروج</a></aside><main><header><div><b>لوحة التحكم</b><span>تحكم كامل بالهوية البصرية</span></div></header><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><section id="design" class="panel"><h2>الألوان والخط</h2><p class="hint">استخدم كود HEX بدقة، ويمكنك أيضاً استخدام منتقي الألوان.</p><div class="swatches"><?php foreach($keys as $k):?><div><i style="background:<?=e(setting($k))?>"></i><span><?=e($k)?></span><code><?=e(setting($k))?></code></div><?php endforeach;?></div><form method="post"><input type="hidden" name="action" value="design"><div class="color-grid"><?php foreach($keys as $k):?><label><?=e(strtoupper($k))?><div class="color-row"><input class="picker" type="color" value="<?=preg_match('/^#[0-9a-fA-F]{6}$/',setting($k))?e(setting($k)):'#000000'?>" data-target="<?=$k?>"><input class="hex" id="<?=$k?>" name="<?=$k?>" value="<?=e(setting($k))?>" pattern="^#[0-9A-Fa-f]{6}$" required></div></label><?php endforeach;?></div><label>نوع الخط<select name="fontFamily"><option <?=setting('fontFamily')==='Expo Arabic'?'selected':''?>>Expo Arabic</option><option <?=setting('fontFamily')==='Cairo'?'selected':''?>>Cairo</option><option <?=setting('fontFamily')==='Tajawal'?'selected':''?>>Tajawal</option><option <?=setting('fontFamily')==='IBM Plex Sans Arabic'?'selected':''?>>IBM Plex Sans Arabic</option><option <?=setting('fontFamily')==='Manrope'?'selected':''?>>Manrope</option><option <?=setting('fontFamily')==='Arial'?'selected':''?>>Arial</option></select></label><label>لون الخط<input class="widehex" name="fontColor" value="<?=e(setting('fontColor','#F5F5F2'))?>" pattern="^#[0-9A-Fa-f]{6}$"><small>يمكن كتابة HEX مثل #F5F5F2</small></label><button>حفظ الهوية البصرية</button></form></section><section id="content" class="panel"><h2>بيانات الموقع</h2><form method="post"><input type="hidden" name="action" value="content"><label>اسم الموقع بالعربية<input name="site_name_ar" value="<?=e(setting('site_name_ar'))?>"></label><label>Site name<input name="site_name_en" value="<?=e(setting('site_name_en'))?>"></label><label>WhatsApp<input name="whatsapp" value="<?=e(setting('whatsapp'))?>"></label><label>Email<input type="email" name="email" value="<?=e(setting('email'))?>"></label><button>حفظ البيانات</button></form></section></main><script>document.querySelectorAll('.picker').forEach(p=>p.addEventListener('input',()=>document.getElementById(p.dataset.target).value=p.value.toUpperCase()));document.querySelectorAll('.hex').forEach(h=>h.addEventListener('input',()=>{if(/^#[0-9a-f]{6}$/i.test(h.value)){const p=document.querySelector('.picker[data-target="'+h.id+'"]');if(p)p.value=h.value}}));</script></body></html>
